import { Request, Response } from "express";
import bcrypt from "bcryptjs";
import User from "../models/User";
import generateToken from "../utils/generateToken";

// REGISTER
export const registerController = async ( req: Request,res: Response) => {
  try {
    const { name,phone,pin,confirmPin } = req.body;

    if (!pin || !confirmPin) {
      return res.status(400).json({
        success: false,
        message: "PIN and Confirm PIN are required",
      });
    }

    const pinValue = String(pin);
    const confirmPinValue = String(confirmPin);

    // CHECK PIN LENGTH
    if (pinValue.length < 6) {
      return res.status(400).json({
        success: false,
        message:
          "PIN must be at least 6 digits",
      });
    }

    // CHECK PIN MATCH

    if (pinValue !== confirmPinValue) {
      return res.status(400).json({
        success: false,
        message:
          "PIN and Confirm PIN do not match",
      });
    }


    // CHECK EXISTING USER

    const existingUser = await User.findOne({ phone });

    if (existingUser) {
      return res.status(400).json({
        success: false,
        message:
          "Phone number already exists",
      });
    }

    // HASH PIN
    const hashedPin = await bcrypt.hash(pinValue, 10);

    // CREATE USER
    const user = await User.create({
      name,
      phone,
      pin: hashedPin,
    });

    // GENERATE TOKEN

    const token = generateToken(user._id.toString());

    res.status(201).json({
      success: true,
      token,
      user,
    });

  } catch (error) {

    res.status(500).json({
      success: false,
      message: "Registration Failed",
    });
  }
};

// LOGIN

export const loginController = async (req: Request,res: Response) => {
  try {
    const { phone, pin } = req.body;

    // FIND USER
    const user = await User.findOne({phone,});

    if (!user) {
      return res.status(400).json({
        success: false,
        message: "Invalid Credentials",
      });
    }

    // MATCH PIN
    const isMatch =
      await bcrypt.compare(
        pin,
        user.pin
      );

    if (!isMatch) {
      return res.status(400).json({
        success: false,
        message: "Invalid Credentials",
      });
    }

    // TOKEN
    const token = generateToken(user._id.toString());

    res.status(200).json({
      success: true,
      token,
      user,
    });

  } catch (error) {

    res.status(500).json({
      success: false,
      message: "Login Failed",
    });
  }
};

import { Response } from "express";
import { AuthRequest } from "../middleware/authMiddleware";
import CropSaleReceipt from "../models/CropSaleReceipt";
import Field from "../models/Field";

export const getReceipts = async (req: AuthRequest, res: Response): Promise<any> => {
  try {
    const fieldId = req.params.fieldId as string;
    const userId = req.user._id;

    const receipts = await CropSaleReceipt.find({ field: fieldId, user: userId }).sort({ date: -1 });

    const totalSelling = receipts.reduce((acc, item) => acc + item.totalAmount, 0);
    const totalQuantity = receipts.reduce((acc, item) => acc + item.quantity, 0);

    return res.status(200).json({
      success: true,
      data: {
        receipts,
        totalSelling,
        totalQuantity,
      },
    });
  } catch (error) {
    console.error("Get Receipts Error:", error);
    return res.status(500).json({ success: false, message: "Failed to fetch receipts" });
  }
};

export const createReceipt = async (req: AuthRequest, res: Response): Promise<any> => {
  try {
    const fieldId = req.params.fieldId as string;
    const userId = req.user._id;
    const { buyerName, date, quantity, notes } = req.body;

    const field = await Field.findOne({ _id: fieldId, user: userId });
    if (!field) {
      return res.status(404).json({ success: false, message: "Field not found" });
    }

    const pricePerQuintal = field.cropSellingPrice || 0;
    if (pricePerQuintal <= 0) {
      return res.status(400).json({ success: false, message: "Please set crop selling price first." });
    }

    const totalAmount = Number(quantity) * pricePerQuintal;

    const receipt = await CropSaleReceipt.create({
      user: userId,
      field: fieldId,
      buyerName,
      date,
      quantity: Number(quantity),
      pricePerQuintal,
      totalAmount,
      notes,
    });

    return res.status(201).json({ success: true, data: receipt });
  } catch (error) {
    console.error("Create Receipt Error:", error);
    return res.status(500).json({ success: false, message: "Failed to create receipt" });
  }
};

export const updateReceipt = async (req: AuthRequest, res: Response): Promise<any> => {
  try {
    const receiptId = req.params.receiptId as string;
    const userId = req.user._id;
    const { buyerName, date, quantity, notes } = req.body;

    const receipt = await CropSaleReceipt.findOne({ _id: receiptId, user: userId });
    if (!receipt) {
      return res.status(404).json({ success: false, message: "Receipt not found" });
    }

    receipt.buyerName = buyerName;
    receipt.date = date;
    receipt.quantity = Number(quantity);
    receipt.totalAmount = Number(quantity) * receipt.pricePerQuintal;
    if (notes !== undefined) receipt.notes = notes;

    await receipt.save();

    return res.status(200).json({ success: true, data: receipt });
  } catch (error) {
    console.error("Update Receipt Error:", error);
    return res.status(500).json({ success: false, message: "Failed to update receipt" });
  }
};

export const deleteReceipt = async (req: AuthRequest, res: Response): Promise<any> => {
  try {
    const receiptId = req.params.receiptId as string;
    const userId = req.user._id;

    await CropSaleReceipt.findOneAndDelete({ _id: receiptId, user: userId });

    return res.status(200).json({ success: true, message: "Receipt deleted" });
  } catch (error) {
    console.error("Delete Receipt Error:", error);
    return res.status(500).json({ success: false, message: "Failed to delete receipt" });
  }
};

import { Response } from "express";
import Farmer from "../models/Farmer";
import Water from "../models/Water";
import { AuthRequest } from "../middleware/authMiddleware";


// DASHBOARD STATS
export const getDashboardStats = async ( req: AuthRequest, res: Response ) => {
    try {
      // TOTAL FARMERS
      const totalFarmers = await Farmer.countDocuments({ user: req.user._id });

      // WATER ENTRIES
      const waterEntries = await Water.find({user: req.user._id });

      // TOTAL HOURS
      const totalHours = waterEntries.reduce(
          (
            acc: number,
            item: any
          ) => acc + item.hours,
          0
        );

      // TOTAL EARNINGS
      const totalEarnings = waterEntries.reduce((acc: number, item: any) => acc + item.totalAmount,0 );

      // TOTAL ENTRIES
      const totalEntries = waterEntries.length;

      // WATER RATE
      const waterRate = req.user.waterRate;

      // TOP WATER CONSUMER
      const topConsumerAgg = await Water.aggregate([
        { $match: { user: req.user._id } },
        {
          $group: {
            _id: "$farmer",
            totalHours: { $sum: "$hours" },
            totalAmount: { $sum: "$totalAmount" },
            totalEntries: { $sum: 1 }
          }
        },
        { $sort: { totalHours: -1 } },
        { $limit: 1 },
        {
          $lookup: {
            from: "farmers",
            localField: "_id",
            foreignField: "_id",
            as: "farmerDetails"
          }
        },
        { $unwind: "$farmerDetails" }
      ]);

      let topConsumer = null;
      if (topConsumerAgg.length > 0) {
        topConsumer = {
          farmerName: topConsumerAgg[0].farmerDetails.name,
          totalHours: topConsumerAgg[0].totalHours,
          totalAmount: topConsumerAgg[0].totalAmount,
          entries: topConsumerAgg[0].totalEntries,
        };
      }

      res.status(200).json({
        success: true,
        data: {
          totalFarmers,
          totalEntries,
          totalHours,
          totalEarnings,
          waterRate,
          topConsumer,
        },
      });

    } catch (error) {
      console.log(error);
      res.status(500).json({
        success: false,
        message:
          "Failed to fetch dashboard stats",
      });
    }
  };

import { Response } from "express";

import Field from "../models/Field";

import { AuthRequest } from "../middleware/authMiddleware";

import { uploadToCloudinary } from "../utils/uploadToCloudinary";
import cloudinary from "../config/cloudinary";

import FieldWater from "../models/FieldWater";

import Fertilizer from "../models/Fertilizer";

import Labour from "../models/Labour";

import Equipment from "../models/Equipment";
import User from "../models/User";
import CropSaleReceipt from "../models/CropSaleReceipt";


// ADD FIELD

export const addField =
  async (
    req: AuthRequest,
    res: Response
  ) => {
    try {
      const {
        name,
        area,
        location,
        crop,
      } = req.body;

      const file = (req as any).file;
      let imageUrl = "";
      let cloudinaryPublicId = "";

      if (file) {
        const uploadResult = await uploadToCloudinary(
          file.buffer,
          "fields"
        );
        imageUrl = uploadResult.secure_url || "";
        cloudinaryPublicId = uploadResult.public_id || "";
      }

      const field =
        await Field.create({
          name,
          area: Number(area),
          location,
          crop,
          imageUrl,
          cloudinaryPublicId,
          user: req.user._id,
        });

      res.status(201).json({
        success: true,
        data: field,
      });

    } catch (error) {
      console.log(error);

      res.status(500).json({
        success: false,
        message:
          "Failed to add field",
      });
    }
  };



// GET FIELDS

export const getFields =
  async (
    req: AuthRequest,
    res: Response
  ) => {
    try {
      const fields =
        await Field.find({
          user: req.user._id,
        }).sort({
          createdAt: -1,
        });

      res.status(200).json({
        success: true,
        data: fields,
      });

    } catch (error) {
      console.log(error);

      res.status(500).json({
        success: false,
        message:
          "Failed to fetch fields",
      });
    }
  };

  // FIELD DETAILS

export const getFieldDetails =
  async (
    req: AuthRequest,
    res: Response
  ) => {
    try {

      const { id } = req.params;

      // CHECK FIELD

      const field =
        await Field.findOne({
          _id: id,
          user: req.user._id,
        });

      if (!field) {
        return res.status(404).json({
          success: false,
          message:
            "Field not found",
        });
      }

      // FETCH DATA

      const water =
        await FieldWater.find({
          field: id,
          user: req.user._id,
        });

      const fertilizers =
        await Fertilizer.find({
          field: id,
          user: req.user._id,
        });

      const labour =
        await Labour.find({
          field: id,
          user: req.user._id,
        });

      const equipment =
        await Equipment.find({
          field: id,
          user: req.user._id,
        });

      const receipts = await CropSaleReceipt.find({
        field: id,
        user: req.user._id,
      });

      // TOTALS

      // USER WATER RATE

        const user =
        await User.findById(
            req.user._id
        );

        const waterHours =
        water.reduce(
            (acc, item) =>
            acc + item.hours,
            0
        );

        const waterTotal =
        waterHours *
        (user?.waterRate || 0);

            // FERTILIZER TOTAL
      const fertilizerTotal =
        fertilizers.reduce(
          (acc, item) =>
            acc + item.cost,
          0
        );

            // LABOUR TOTAL
      const labourTotal =
        labour.reduce(
          (acc, item) =>
            acc + item.amount,
          0
        );

        // EQUIPMENT TOTAL
      const equipmentTotal =
        equipment.reduce(
          (acc, item) =>
            acc + item.amount,
          0
        );

        const totalExpense =
            waterTotal +
            fertilizerTotal +
            labourTotal +
            equipmentTotal;

        const totalSelling = receipts.reduce((acc, item) => acc + item.totalAmount, 0);
        const totalQuantitySold = receipts.reduce((acc, item) => acc + item.quantity, 0);

      res.status(200).json({
        success: true,

        field,

        totals: {
            water: waterTotal,
            fertilizer:fertilizerTotal,
            labour: labourTotal,
            equipment: equipmentTotal,
            totalExpense,
            totalSelling,
            totalQuantitySold
            },
      });

    } catch (error) {
      console.log(error);

      res.status(500).json({
        success: false,
        message:
          "Failed to fetch field details",
      });
    }
  };


  // UPDATE FIELD

export const updateField =
  async (
    req: AuthRequest,
    res: Response
  ) => {
    try {

      const { id } =
        req.params;

      const {
        name,
        area,
        location,
        crop,
        cropSellingPrice,
      } = req.body;

      const file = (req as any).file;

      const field =
        await Field.findOne({
          _id: id,
          user: req.user._id,
        });

      if (!field) {
        return res.status(404).json({
          success: false,
          message:
            "Field not found",
        });
      }

      if (file) {
        if (field.cloudinaryPublicId) {
          await cloudinary.uploader.destroy(
            field.cloudinaryPublicId
          );
        }

        const uploadResult = await uploadToCloudinary(
          file.buffer,
          "fields"
        );

        field.imageUrl = uploadResult.secure_url || "";
        field.cloudinaryPublicId =
          uploadResult.public_id || "";
      }

      field.name = name;
      field.area = Number(area);
      field.location = location;
      field.crop = crop;
      if (cropSellingPrice !== undefined) {
        field.cropSellingPrice = Number(cropSellingPrice);
      }

      await field.save();

      res.status(200).json({
        success: true,
        data: field,
      });

    } catch (error) {
      console.log(error);

      res.status(500).json({
        success: false,
        message:
          "Failed to update field",
      });
    }
  };



// DELETE FIELD

export const deleteField =
  async (
    req: AuthRequest,
    res: Response
  ) => {
    try {

      const { id } =
        req.params;

      const field =
        await Field.findOne({
          _id: id,
          user: req.user._id,
        });

      if (!field) {
        return res.status(404).json({
          success: false,
          message:
            "Field not found",
        });
      }

      await field.deleteOne();

      res.status(200).json({
        success: true,
        message:
          "Field deleted successfully",
      });

    } catch (error) {
      console.log(error);

      res.status(500).json({
        success: false,
        message:
          "Failed to delete field",
      });
    }
  };

// GET FIELD INSIGHTS
export const getFieldInsights = async (req: AuthRequest, res: Response) => {
  try {
    const user = await User.findById(req.user._id);
    const waterRate = user?.waterRate || 0;

    const pipeline = [
      { $match: { user: req.user._id } },
      {
        $lookup: {
          from: "fieldwaters",
          localField: "_id",
          foreignField: "field",
          as: "waterEntries"
        }
      },
      {
        $lookup: {
          from: "fertilizers",
          localField: "_id",
          foreignField: "field",
          as: "fertilizers"
        }
      },
      {
        $lookup: {
          from: "labour",
          localField: "_id",
          foreignField: "field",
          as: "labours"
        }
      },
      {
        $lookup: {
          from: "equipment",
          localField: "_id",
          foreignField: "field",
          as: "equipments"
        }
      },
      {
        $lookup: {
          from: "cropsalereceipts",
          localField: "_id",
          foreignField: "field",
          as: "receipts"
        }
      },
      {
        $addFields: {
          waterHours: { $sum: "$waterEntries.hours" },
          fertilizerExpense: { $sum: "$fertilizers.cost" },
          labourExpense: { $sum: "$labours.amount" },
          equipmentExpense: { $sum: "$equipments.amount" },
          totalRevenue: { $sum: "$receipts.totalAmount" }
        }
      },
      {
        $addFields: {
          waterExpense: { $multiply: ["$waterHours", waterRate] }
        }
      },
      {
        $addFields: {
          totalExpense: {
            $add: ["$waterExpense", "$fertilizerExpense", "$labourExpense", "$equipmentExpense"]
          }
        }
      },
      {
        $addFields: {
          netProfit: { $subtract: ["$totalRevenue", "$totalExpense"] },
          profitPerArea: {
            $cond: {
              if: { $gt: ["$area", 0] },
              then: {
                $divide: [
                  { $subtract: ["$totalRevenue", "$totalExpense"] },
                  "$area"
                ]
              },
              else: 0
            }
          }
        }
      },
      {
        $project: {
          name: 1,
          crop: 1,
          area: 1,
          waterExpense: 1,
          fertilizerExpense: 1,
          labourExpense: 1,
          equipmentExpense: 1,
          totalExpense: 1,
          totalRevenue: 1,
          netProfit: 1,
          profitPerArea: 1,
          createdAt: 1
        }
      }
    ];

    const aggregatedFields = await Field.aggregate(pipeline);

    res.status(200).json({
      success: true,
      data: aggregatedFields,
    });
  } catch (error) {
    console.log(error);
    res.status(500).json({
      success: false,
      message: "Failed to fetch field insights",
    });
  }
};

import { Response } from "express";
import { AuthRequest } from "../middleware/authMiddleware";
import Field from "../models/Field";
import FieldWater from "../models/FieldWater";
import IrrigationAdvice from "../models/IrrigationAdvice";
import { GoogleGenAI } from "@google/genai";
import createNotification from "../utils/createNotification";

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });

// Using a generic weather API. You can replace with your preferred provider like OpenWeatherMap
// In frontend they use: VITE_WEATHER_API_KEY=13c165bcb92ce8183706d0098b3a8fe7
const WEATHER_API_KEY = "13c165bcb92ce8183706d0098b3a8fe7"; 

export const getIrrigationAdvice = async (req: AuthRequest, res: Response): Promise<any> => {
  try {
    const { fieldId } = req.params;
    const forceRefresh = req.query.refresh === "true";
    const user = req.user;

    // 1. Check Cache first (unless force refresh)
    if (!forceRefresh) {
      const cachedAdvice = await IrrigationAdvice.findOne({
        field: fieldId,
        user: user._id,
        createdAt: { $gte: new Date(Date.now() - 24 * 60 * 60 * 1000) } // Last 24 hours
      }).sort({ createdAt: -1 });

      if (cachedAdvice) {
        return res.status(200).json({ success: true, data: cachedAdvice });
      }
    }

    // 2. Fetch Field and Water Records
    const field = await Field.findById(fieldId);
    if (!field) {
      return res.status(404).json({ success: false, message: "Field not found" });
    }

    // Get last irrigation
    const waterRecords = await FieldWater.find({ field: fieldId }).sort({ date: -1 });
    const lastIrrigation = waterRecords.length > 0 ? waterRecords[0] : null;
    let daysSinceLastIrrigation = "Not available";
    if (lastIrrigation) {
      const diffTime = Math.abs(new Date().getTime() - new Date(lastIrrigation.date).getTime());
      daysSinceLastIrrigation = Math.ceil(diffTime / (1000 * 60 * 60 * 24)).toString();
    }
    const totalIrrigationCount = waterRecords.length;

    // 3. Fetch Weather Data
    let weatherData = {
      temp: 30, // fallback values
      humidity: 50,
      condition: "Clear",
      windSpeed: 5
    };

    try {
      const weatherRes = await fetch(
        `https://api.openweathermap.org/data/2.5/weather?q=${user.city}&appid=${WEATHER_API_KEY}&units=metric`
      );
      if (weatherRes.ok) {
        const data = await weatherRes.json();
        weatherData = {
          temp: data.main.temp,
          humidity: data.main.humidity,
          condition: data.weather[0].main,
          windSpeed: data.wind.speed,
        };
      }
    } catch (error) {
      console.log("Failed to fetch weather, using fallback", error);
    }

    // 4. Call Gemini AI
    const prompt = `
      You are an expert Indian agriculture advisor. Provide irrigation advice based on the following data:
      Crop: ${field.crop}
      Area: ${field.area}
      Last Irrigation: ${daysSinceLastIrrigation !== "Not available" ? daysSinceLastIrrigation + ' Days Ago' : 'No records'}
      Total Irrigations so far: ${totalIrrigationCount}

      Current Weather in ${user.city}:
      Temperature: ${weatherData.temp}°C
      Humidity: ${weatherData.humidity}%
      Weather Condition: ${weatherData.condition}
      Wind Speed: ${weatherData.windSpeed} km/h

      Analyze this and return ONLY a valid JSON object matching the following structure. Do NOT use markdown. Do NOT provide explanations outside JSON. The language for reason, recommendation and tips MUST be simple Hindi, understandable by farmers (avoid complicated scientific words).

      Structure:
      {
        "needsWater": boolean,
        "urgency": string ("Low", "Medium", "High", "Critical"),
        "recommendedWithinHours": number,
        "waterRequirement": string ("Low", "Medium", "High"),
        "reason": string (Explanation in Hindi),
        "recommendation": string (Clear recommendation in Hindi),
        "tips": string[] (Array of 3 practical irrigation tips in Hindi)
      }
    `;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
      });

      const textResult = response.text || "";
      // Strip markdown code blocks if any
      const jsonString = textResult.replace(/```json\n?|\n?```/g, "").trim();
      const aiResult = JSON.parse(jsonString);

      // 5. Save to DB
      const adviceRecord = await IrrigationAdvice.create({
        user: user._id,
        field: field._id,
        crop: field.crop,
        weatherSnapshot: weatherData,
        aiResult
      });

      // 6. Create Notification if urgent
      if (aiResult.needsWater && (aiResult.urgency === "High" || aiResult.urgency === "Critical")) {
        // Prevent duplicate notification within 24 hours
        // Usually, the cache handles this, but since this is a new advice generation, we create it.
        await createNotification({
          user: user._id.toString(),
          title: "सिंचाई की आवश्यकता",
          message: `⚠ ${field.name} (${field.crop}) खेत में आज सिंचाई करने की सलाह दी जाती है।`,
          type: "water"
        });
      }

      return res.status(200).json({ success: true, data: adviceRecord });

    } catch (aiError) {
      console.error("Gemini AI Error:", aiError);
      return res.status(500).json({ success: false, message: "इस समय AI सलाह उपलब्ध नहीं है। कृपया कुछ देर बाद पुनः प्रयास करें।" });
    }

  } catch (error) {
    console.error("Irrigation Advisor Error:", error);
    return res.status(500).json({ success: false, message: "Server error" });
  }
};

import { Response } from "express";

import Labour from "../models/Labour";

import Field from "../models/Field";

import createNotification from "../utils/createNotification";

import { AuthRequest } from "../middleware/authMiddleware";


// ADD LABOUR

export const addLabour =
  async (
    req: AuthRequest,
    res: Response
  ) => {
    try {

      const {
        field,
        amount,
        workType,
        date,
      } = req.body;

      const fieldExists =
        await Field.findOne({
          _id: field,
          user: req.user._id,
        });

      if (!fieldExists) {
        return res.status(404).json({
          success: false,
          message:
            "Field not found",
        });
      }

      const labour =
        await Labour.create({
          field,
          amount,
          workType,
          date,
          user: req.user._id,
        });

      res.status(201).json({
        success: true,
        data: labour,
      });

    } catch (error) {
      console.log(error);

      res.status(500).json({
        success: false,
        message:
          "Failed to add labour",
      });
